import json
import math
import time
from collections import Counter
from collections.abc import Mapping
from importlib.metadata import version
from itertools import combinations

import networkx as nx
import numpy as np
from qiskit import QuantumCircuit, transpile
from qiskit.circuit import ParameterVector
from qiskit_aer import AerSimulator
from scipy.optimize import minimize


STATION_COORDINATES_M = {
    "S0": (0.0, 0.5),
    "S1": (0.0, 1.5),
    "S2": (3.0, 0.0),
    "S3": (3.0, 1.0),
    "S4": (3.0, 2.0),
    "S5": (6.0, 0.0),
    "S6": (6.0, 1.0),
    "S7": (6.0, 2.0),
    "S8": (9.0, 0.5),
    "S9": (9.0, 1.5),
}

STATION_STAGE = {
    "S0": 0, "S1": 0,
    "S2": 1, "S3": 1, "S4": 1,
    "S5": 2, "S6": 2, "S7": 2,
    "S8": 3, "S9": 3,
}

STAGE_NAMES = ("Design", "Fabrication", "Testing", "Shipping")

TASK_EDGES = (
    ("S0", "S1"),
    ("S2", "S3"),
    ("S3", "S4"),
    ("S5", "S6"),
    ("S6", "S7"),
    ("S8", "S9"),
    ("S0", "S2"),
    ("S0", "S3"),
    ("S1", "S3"),
    ("S1", "S4"),
    ("S2", "S5"),
    ("S3", "S6"),
    ("S4", "S7"),
    ("S5", "S8"),
    ("S6", "S8"),
    ("S6", "S9"),
    ("S7", "S9"),
)


def build_station_graph(
    graph_vertices=None,
    same_stage_radius_m=1.5,
    cross_stage_radius_m=3.1,
):
    """Compute every pairwise distance; never infer edges from x-position alone."""
    vertices = (
        list(STATION_COORDINATES_M)
        if graph_vertices is None
        else list(graph_vertices)
    )
    if len(set(vertices)) != len(vertices):
        raise ValueError("Station labels must be unique.")
    if not set(vertices).issubset(STATION_COORDINATES_M):
        raise ValueError("Coordinates are unavailable for one or more stations.")
    if same_stage_radius_m < 0 or cross_stage_radius_m < 0:
        raise ValueError("Connection radii must be nonnegative.")

    graph = nx.Graph()
    for vertex in vertices:
        graph.add_node(
            vertex,
            coordinates_m=STATION_COORDINATES_M[vertex],
            stage=STAGE_NAMES[STATION_STAGE[vertex]],
        )

    pairwise_distances = []
    for u, v in combinations(vertices, 2):
        distance = math.dist(
            STATION_COORDINATES_M[u], STATION_COORDINATES_M[v]
        )
        stage_difference = abs(STATION_STAGE[u] - STATION_STAGE[v])
        kind = None
        applicable_radius = None

        if stage_difference == 0:
            applicable_radius = same_stage_radius_m
            if distance <= applicable_radius + 1e-12:
                kind = "shared_fixture"
        elif stage_difference == 1:
            applicable_radius = cross_stage_radius_m
            if distance <= applicable_radius + 1e-12:
                kind = "conveyor"

        pairwise_distances.append({
            "stations": [u, v],
            "distance_m": float(distance),
            "stage_separation": stage_difference,
            "applicable_radius_m": applicable_radius,
            "connected": kind is not None,
            "link_type": kind,
        })
        if kind is not None:
            graph.add_edge(u, v, distance_m=float(distance), link_type=kind)

    return graph, pairwise_distances


def _read_reference_partition(reference, vertices):
    """Accept two groups, a binary assignment, or a vertex-to-line mapping."""
    if reference is None:
        return None

    n = len(vertices)
    vertex_set = set(vertices)

    if isinstance(reference, Mapping):
        if set(reference) == vertex_set:
            labels = list(dict.fromkeys(reference[v] for v in vertices))
            if len(labels) != 2:
                raise ValueError("A reference assignment must contain two lines.")
            bits = [int(reference[v] == labels[1]) for v in vertices]
            return _validate_reference_bits(bits, n)
        if len(reference) != 2:
            raise ValueError("A reference group mapping must contain two groups.")
        reference = list(reference.values())

    if isinstance(reference, str):
        if len(reference) != n or set(reference) - {"0", "1"}:
            raise ValueError("A reference bit string must have one bit per vertex.")
        # Unlike Qiskit count strings, this string follows graph_vertices order.
        return _validate_reference_bits([int(b) for b in reference], n)

    items = list(reference)
    if len(items) == n and all(
        isinstance(x, (int, np.integer, bool)) and int(x) in (0, 1)
        for x in items
    ):
        return _validate_reference_bits([int(x) for x in items], n)

    if len(items) != 2:
        raise ValueError("Reference partition must specify two disjoint groups.")
    left, right = set(items[0]), set(items[1])
    if left & right or left | right != vertex_set:
        raise ValueError("Reference groups must partition all vertices exactly.")
    return _validate_reference_bits([int(v in right) for v in vertices], n)


def _validate_reference_bits(bits, n):
    if sum(bits) not in {n // 2, (n + 1) // 2}:
        raise ValueError("The reference partition must be maximally balanced.")
    return sum(int(bit) << i for i, bit in enumerate(bits))


def _canonical_mask(mask, n):
    """Identify partitions related only by exchanging the two line labels."""
    return min(int(mask), ((1 << n) - 1) ^ int(mask))


def _partition_from_mask(mask, vertices):
    return {
        "line_1": [v for i, v in enumerate(vertices) if not ((mask >> i) & 1)],
        "line_2": [v for i, v in enumerate(vertices) if (mask >> i) & 1],
    }


def _repair_and_polish(mask, n, cuts):
    """Greedy balance repair followed by strictly improving balanced swaps."""
    mask = int(mask)
    if mask.bit_count() not in {n // 2, (n + 1) // 2}:
        target = n // 2
        while mask.bit_count() != target:
            remove_one = mask.bit_count() > target
            candidates = [
                mask ^ (1 << i)
                for i in range(n)
                if bool((mask >> i) & 1) == remove_one
            ]
            mask = min(candidates, key=lambda m: (int(cuts[m]), m))

    while True:
        best = mask
        best_cost = int(cuts[mask])
        zeros = [i for i in range(n) if not ((mask >> i) & 1)]
        ones = [i for i in range(n) if (mask >> i) & 1]
        for i in zeros:
            for j in ones:
                candidate = mask ^ (1 << i) ^ (1 << j)
                cost = int(cuts[candidate])
                if cost < best_cost:
                    best, best_cost = candidate, cost
        if best == mask:
            return _canonical_mask(mask, n)
        mask = best


def _minimization_ratio(value, optimum):
    """For minimization, achieved/optimal >= 1; None denotes an infinite ratio."""
    if optimum == 0:
        return 1.0 if value == 0 else None
    return float(value / optimum)


def solve_graph_partition_qaoa(
    graph_vertices,
    graph_edges,
    known_reference_partition,
    p_layers=2,
    lambda_balance=1.0,
    lambda_cut=3.0,
    opt_shots=1024,
    final_shots=4096,
    maxiter=100,
    n_repro_runs=3,
    seed=42,
):
    """
    Shot-based QAOA plus balanced classical swap refinement.

    E(x) = lambda_cut * cut_all_links(x)
           + lambda_balance * (sum(x) - n/2)^2.

    Both fixture and conveyor edges belong to the unweighted station graph.
    The graph-cut objective penalizes all inter-line links. Conveyor-only
    crossings are additionally counted and independently benchmarked, so they
    are not confused with fixture crossings.

    Final partitions satisfy the strongest possible cardinality balance,
    regardless of whether the soft penalty alone enforces it. No requirement
    that each line contain every stage is imposed, because none was specified.

    Exact enumeration is used only for benchmarking this small instance, never
    to inject an optimum into the quantum candidate set.
    """
    total_start = time.perf_counter()

    integer_options = {
        "p_layers": p_layers,
        "opt_shots": opt_shots,
        "final_shots": final_shots,
        "maxiter": maxiter,
        "n_repro_runs": n_repro_runs,
    }
    for name, value in integer_options.items():
        if isinstance(value, bool) or not isinstance(value, (int, np.integer)):
            raise ValueError(f"{name} must be a positive integer.")
        if value < 1:
            raise ValueError(f"{name} must be positive.")

    lambda_balance = float(lambda_balance)
    lambda_cut = float(lambda_cut)
    if not math.isfinite(lambda_balance) or lambda_balance < 0:
        raise ValueError("lambda_balance must be finite and nonnegative.")
    if not math.isfinite(lambda_cut) or lambda_cut <= 0:
        raise ValueError("lambda_cut must be finite and positive.")
    if isinstance(seed, bool) or not isinstance(seed, (int, np.integer)):
        raise ValueError("seed must be an integer.")
    seed = int(seed)
    if not 0 <= seed < 2**32:
        raise ValueError("seed must be in [0, 2**32).")

    vertices = list(graph_vertices)
    n = len(vertices)
    if not 2 <= n <= 20 or len(set(vertices)) != n:
        raise ValueError("Use 2 to 20 distinct vertices for this small-instance solver.")

    vertex_set = set(vertices)
    supplied_edges = set()
    if graph_edges is not None:
        for edge in graph_edges:
            edge = tuple(edge)
            if len(edge) != 2:
                raise ValueError("Each edge must have two endpoints.")
            u, v = edge
            if u not in vertex_set or v not in vertex_set or u == v:
                raise ValueError("Edges must connect two distinct declared vertices.")
            supplied_edges.add(frozenset((u, v)))

    geometry_available = vertex_set.issubset(STATION_COORDINATES_M)
    if geometry_available:
        graph, distances = build_station_graph(vertices)
        geometric_edges = {frozenset(e) for e in graph.edges()}
        if graph_edges is not None and supplied_edges != geometric_edges:
            raise ValueError(
                "graph_edges disagrees with the graph computed from both "
                "distance rules; missing or spurious geometric links detected."
            )
    else:
        if graph_edges is None:
            raise ValueError("graph_edges is required when coordinates are unknown.")
        graph = nx.Graph()
        graph.add_nodes_from(vertices)
        # Preserve deterministic vertex-pair ordering.
        for u, v in combinations(vertices, 2):
            if frozenset((u, v)) in supplied_edges:
                graph.add_edge(u, v, link_type="unspecified")
        distances = []

    index = {v: i for i, v in enumerate(vertices)}
    indexed_edges = [(index[u], index[v]) for u, v in graph.edges()]
    conveyor_edges = [
        (index[u], index[v])
        for u, v, data in graph.edges(data=True)
        if data.get("link_type") == "conveyor"
    ]

    masks = np.arange(1 << n, dtype=np.uint64)
    weights = np.fromiter(
        (int(mask).bit_count() for mask in masks),
        dtype=np.int16,
        count=len(masks),
    )
    cuts = np.zeros(len(masks), dtype=np.int32)
    conveyor_cuts = np.zeros(len(masks), dtype=np.int32)
    for i, j in indexed_edges:
        cuts += (((masks >> i) ^ (masks >> j)) & 1).astype(np.int32)
    for i, j in conveyor_edges:
        conveyor_cuts += (((masks >> i) ^ (masks >> j)) & 1).astype(np.int32)

    energies = (
        lambda_cut * cuts
        + lambda_balance * (weights.astype(float) - n / 2.0) ** 2
    )
    feasible = (weights == n // 2) | (weights == (n + 1) // 2)

    exact_optimum = int(cuts[feasible].min())
    exact_conveyor_optimum = (
        int(conveyor_cuts[feasible].min()) if geometry_available else None
    )
    reference_mask = _read_reference_partition(
        known_reference_partition, vertices
    )

    def metrics(mask):
        partition = _partition_from_mask(mask, vertices)
        left = set(partition["line_1"])
        right = set(partition["line_2"])
        cut = int(cuts[mask])
        volume_left = sum(graph.degree(v) for v in left)
        volume_right = sum(graph.degree(v) for v in right)
        # A zero-volume community has no incident cut edges; its contribution
        # to normalized cut is defined as zero here.
        normalized_cut = (
            (cut / volume_left if volume_left else 0.0)
            + (cut / volume_right if volume_right else 0.0)
        )
        modularity = (
            nx.algorithms.community.modularity(
                graph, [left, right], weight=None
            )
            if graph.number_of_edges()
            else 0.0
        )
        return {
            "modularity_score": float(modularity),
            "normalized_cut_score": float(normalized_cut),
            "balance_constraint_score": float(
                1.0 - abs(len(left) - len(right)) / n
            ),
            "approximation_ratio": _minimization_ratio(cut, exact_optimum),
            "cut_edges": cut,
            "conveyor_crossings": (
                int(conveyor_cuts[mask]) if geometry_available else None
            ),
            "same_stage_crossings": (
                cut - int(conveyor_cuts[mask]) if geometry_available else None
            ),
        }

    gammas = ParameterVector("gamma", p_layers)
    betas = ParameterVector("beta", p_layers)
    circuit = QuantumCircuit(n)
    circuit.h(range(n))

    edge_indices = {tuple(sorted(edge)) for edge in indexed_edges}
    for layer in range(p_layers):
        # x_i = (1-Z_i)/2 gives the ZZ coefficient
        # J_ij = lambda_balance/2 - lambda_cut*A_ij/2.
        # RZZ(theta) = exp(-i*theta*Z_i*Z_j/2); constants are global phases.
        for i, j in combinations(range(n), 2):
            angle_coefficient = (
                lambda_balance
                - lambda_cut * int((i, j) in edge_indices)
            )
            if angle_coefficient != 0.0:
                circuit.rzz(angle_coefficient * gammas[layer], i, j)
        for i in range(n):
            circuit.rx(2.0 * betas[layer], i)
    circuit.measure_all()

    backend = AerSimulator(
        method="statevector",
        max_parallel_threads=1,
        max_parallel_experiments=1,
    )
    compiled = transpile(
        circuit,
        backend=backend,
        optimization_level=1,
        seed_transpiler=seed,
    )

    def sample(parameters, shots, simulator_seed):
        bindings = {
            gammas[layer]: float(parameters[layer])
            for layer in range(p_layers)
        }
        bindings.update({
            betas[layer]: float(parameters[p_layers + layer])
            for layer in range(p_layers)
        })
        bound = compiled.assign_parameters(bindings, inplace=False)
        counts = backend.run(
            bound,
            shots=int(shots),
            seed_simulator=int(simulator_seed),
        ).result().get_counts()
        # Qiskit displays q_(n-1)...q_0; integer bit i corresponds to vertex i.
        return {
            int(bitstring.replace(" ", ""), 2): int(count)
            for bitstring, count in counts.items()
        }

    runs = []
    run_masks = []
    for run_index in range(n_repro_runs):
        run_start = time.perf_counter()
        run_seed = (seed + 104729 * run_index) % (2**32)
        final_seed = (run_seed + 32452843) % (2**32)
        rng = np.random.default_rng(run_seed)
        initial_parameters = np.concatenate((
            rng.uniform(0.0, np.pi, p_layers),
            rng.uniform(0.0, np.pi / 2.0, p_layers),
        ))

        incumbent = {"energy": math.inf, "parameters": None, "evaluations": 0}

        def objective(parameters):
            # Fixed common-random-number seed makes repeated evaluations of
            # identical parameters deterministic within a pinned environment.
            counts = sample(parameters, opt_shots, run_seed)
            expectation = float(
                sum(float(energies[m]) * count for m, count in counts.items())
                / sum(counts.values())
            )
            incumbent["evaluations"] += 1
            if expectation < incumbent["energy"]:
                incumbent["energy"] = expectation
                incumbent["parameters"] = np.asarray(parameters, dtype=float).copy()
            return expectation

        optimization = minimize(
            objective,
            initial_parameters,
            method="COBYLA",
            options={
                "maxiter": int(maxiter),
                "rhobeg": 0.5,
                "tol": 1e-3,
                "disp": False,
            },
        )
        parameters = incumbent["parameters"]
        final_counts = sample(parameters, final_shots, final_seed)
        balanced_counts = {
            mask: count
            for mask, count in final_counts.items()
            if bool(feasible[mask])
        }

        if balanced_counts:
            candidates = sorted(
                balanced_counts,
                key=lambda m: (int(cuts[m]), -balanced_counts[m], m),
            )[:32]
        else:
            candidates = sorted(
                final_counts,
                key=lambda m: (float(energies[m]), -final_counts[m], m),
            )[:32]

        polished = [
            _repair_and_polish(mask, n, cuts) for mask in candidates
        ]
        selected_mask = min(polished, key=lambda m: (int(cuts[m]), m))
        selected_metrics = metrics(selected_mask)
        run_masks.append(selected_mask)
        runs.append({
            "run_index": run_index,
            "seed": run_seed,
            "final_sampling_seed": final_seed,
            "partition": _partition_from_mask(selected_mask, vertices),
            **selected_metrics,
            "optimized_parameters": {
                "gamma": [float(x) for x in parameters[:p_layers]],
                "beta": [float(x) for x in parameters[p_layers:]],
            },
            "optimized_shot_expectation": float(incumbent["energy"]),
            "final_shot_expectation": float(
                sum(float(energies[m]) * c for m, c in final_counts.items())
                / sum(final_counts.values())
            ),
            "balanced_sample_probability": float(
                sum(balanced_counts.values()) / sum(final_counts.values())
            ),
            "optimal_balanced_sample_probability": float(
                sum(
                    c for m, c in balanced_counts.items()
                    if int(cuts[m]) == exact_optimum
                ) / sum(final_counts.values())
            ),
            "best_measured_balanced_cut": (
                min(int(cuts[m]) for m in balanced_counts)
                if balanced_counts else None
            ),
            "balance_repair_needed": not bool(balanced_counts),
            "classical_swap_refinement_used": True,
            "objective_evaluations": incumbent["evaluations"],
            "optimizer_success": bool(optimization.success),
            "optimizer_message": str(optimization.message),
            "runtime_seconds": float(time.perf_counter() - run_start),
        })

    selected_run_index = min(
        range(n_repro_runs),
        key=lambda i: (int(cuts[run_masks[i]]), run_masks[i], i),
    )
    selected_mask = run_masks[selected_run_index]
    result_metrics = metrics(selected_mask)
    frequencies = Counter(run_masks)

    summary = {}
    for name in (
        "modularity_score",
        "normalized_cut_score",
        "balance_constraint_score",
        "approximation_ratio",
        "cut_edges",
    ):
        values = [run[name] for run in runs]
        if any(value is None for value in values):
            summary[name] = {"mean": None, "std": None}
        else:
            summary[name] = {
                "mean": float(np.mean(values)),
                "std": float(np.std(values, ddof=0)),
            }

    crossing_links = []
    graph_links = []
    for u, v, data in graph.edges(data=True):
        link = {
            "stations": [u, v],
            "link_type": data.get("link_type"),
        }
        if "distance_m" in data:
            link["distance_m"] = float(data["distance_m"])
        graph_links.append(link)
        if ((selected_mask >> index[u]) ^ (selected_mask >> index[v])) & 1:
            crossing_links.append(dict(link))

    result = {
        **result_metrics,
        "partition": _partition_from_mask(selected_mask, vertices),
        "selected_run_index": selected_run_index,
        "crossing_links": crossing_links,
        "conveyor_approximation_ratio": (
            _minimization_ratio(
                result_metrics["conveyor_crossings"], exact_conveyor_optimum
            )
            if geometry_available else None
        ),
        "benchmark": {
            "method": "exhaustive enumeration of maximally balanced assignments",
            "used_to_seed_or_replace_quantum_solution": False,
            "optimal_balanced_cut": exact_optimum,
            "optimal_balanced_conveyor_crossings": exact_conveyor_optimum,
            "balanced_assignments_checked": int(np.count_nonzero(feasible)),
            "known_reference_partition": (
                _partition_from_mask(reference_mask, vertices)
                if reference_mask is not None else None
            ),
            "known_reference_metrics": (
                metrics(reference_mask) if reference_mask is not None else None
            ),
        },
        "graph": {
            "vertices": vertices,
            "number_of_vertices": n,
            "number_of_edges": graph.number_of_edges(),
            "edges": graph_links,
            "pairwise_distances": distances,
            "geometry_verified": geometry_available,
            "same_stage_radius_m": 1.5 if geometry_available else None,
            "cross_stage_radius_m": 3.1 if geometry_available else None,
        },
        "configuration": {
            **{name: int(value) for name, value in integer_options.items()},
            "lambda_balance": lambda_balance,
            "lambda_cut": lambda_cut,
            "optimizer": "COBYLA",
            "backend": "qiskit_aer.AerSimulator(method='statevector')",
            "objective": (
                "lambda_cut * all_link_cut + "
                "lambda_balance * (line_2_size - n/2)^2"
            ),
            "postprocessing": (
                "Keep balanced samples; repair only if none were sampled; "
                "apply improving cardinality-preserving swaps to at most "
                "32 measured candidates."
            ),
            "compiled_circuit_depth": compiled.depth(),
        },
        "metric_definitions": {
            "modularity_score": "Unweighted Newman-Girvan modularity on all links.",
            "normalized_cut_score": (
                "cut/volume(line_1) + cut/volume(line_2), using all links."
            ),
            "balance_constraint_score": (
                "1 - abs(line_1_size - line_2_size)/n; 1 is perfect balance."
            ),
            "approximation_ratio": (
                "Achieved all-link cut / exact optimal balanced all-link cut; "
                "1 is optimal, larger is worse. 0/0 is reported as 1; "
                "positive/0 is reported as null."
            ),
            "runtime": "Total wall-clock seconds, including all independent runs.",
            "conveyor_crossings": "Only adjacent-stage conveyor edges crossing lines.",
        },
        "reproducibility": {
            "base_seed": seed,
            "n_runs": int(n_repro_runs),
            "seeds": [run["seed"] for run in runs],
            "transpiler_seed": seed,
            "simulator_threads": 1,
            "sampling": "Finite-shot, noiseless statevector simulation.",
            "seed_policy": (
                "Independent optimization seeds across runs; fixed simulator "
                "seed within each run; separate fixed final-sampling seed."
            ),
            "repeatability": (
                "Rerunning with the same inputs, seeds, and software environment "
                "reproduces the algorithmic results; wall-clock timings vary. "
                "The multi-seed runs measure stochastic robustness."
            ),
            "software_versions": {
                package: version(package)
                for package in ("qiskit", "qiskit-aer", "numpy", "scipy", "networkx")
            },
            "identical_partition_fraction": float(
                max(frequencies.values()) / n_repro_runs
            ),
            "selected_partition_fraction": float(
                frequencies[selected_mask] / n_repro_runs
            ),
            "exact_optimum_hit_fraction": float(
                sum(int(cuts[m]) == exact_optimum for m in run_masks)
                / n_repro_runs
            ),
            "partition_frequencies": [
                {
                    "partition": _partition_from_mask(mask, vertices),
                    "count": count,
                }
                for mask, count in sorted(frequencies.items())
            ],
            "metric_summary": summary,
            "runs": runs,
        },
    }
    result["runtime"] = float(time.perf_counter() - total_start)
    return result


def main():
    vertices = list(STATION_COORDINATES_M)
    reference_partition = (vertices[:5], vertices[5:])
    result = solve_graph_partition_qaoa(
        graph_vertices=vertices,
        graph_edges=TASK_EDGES,
        known_reference_partition=reference_partition,
        p_layers=2,
        lambda_balance=1.0,
        lambda_cut=3.0,
        opt_shots=1024,
        final_shots=4096,
        maxiter=100,
        n_repro_runs=3,
        seed=42,
    )
    print(json.dumps(result, indent=2, allow_nan=False))


if __name__ == "__main__":
    main()

